import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Calendar, Users, Clock, DollarSign, Star, TrendingUp, CheckCircle, XCircle, AlertCircle, Plus, Eye, Edit, Settings } from 'lucide-react';
import { appointmentService, providerService } from '../services/api';
import { Card, StatCard, Button, StatusBadge, Spinner, PageHeader } from '../components/UI';
import { format } from 'date-fns';
import toast from 'react-hot-toast';

// Get the logged-in provider's ID from user data or use demo as fallback
const getProviderId = () => {
  try {
    const user = JSON.parse(localStorage.getItem('medibook_user') || '{}');
    return user.userId || 'provider-001';
  } catch {
    return 'provider-001';
  }
};

export default function ProviderDashboard() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [appointments, setAppointments] = useState([]);
  const [provider, setProvider] = useState(null);
  const [stats, setStats] = useState({
    totalAppointments: 0,
    completedAppointments: 0,
    upcomingAppointments: 0,
    totalRevenue: 0,
    averageRating: 0,
  });

  useEffect(() => {
    async function fetchProviderData() {
      try {
        setLoading(true);

        const providerId = getProviderId();
        console.log('Fetching data for provider:', providerId);

        // Try to fetch provider information
        try {
          const providerRes = await providerService.getById(providerId);
          if (providerRes.data) {
            setProvider(providerRes.data);
            console.log('Found provider data:', providerRes.data);

            // Fetch appointments for this provider
            try {
              const appointmentsRes = await appointmentService.getByProvider(providerId);
              if (appointmentsRes.data) {
                setAppointments(appointmentsRes.data);

                // Calculate stats
                const completed = appointmentsRes.data.filter(apt => apt.status === 'Completed').length;
                const upcoming = appointmentsRes.data.filter(apt => apt.status === 'Scheduled').length;
                const revenue = appointmentsRes.data
                  .filter(apt => apt.status === 'Completed')
                  .reduce((sum, apt) => sum + (apt.fee || 0), 0);

                setStats({
                  totalAppointments: appointmentsRes.data.length,
                  completedAppointments: completed,
                  upcomingAppointments: upcoming,
                  totalRevenue: revenue,
                  averageRating: providerRes.data?.rating || 4.5,
                });
              } else {
                // No appointments found, set default stats
                setStats({
                  totalAppointments: 0,
                  completedAppointments: 0,
                  upcomingAppointments: 0,
                  totalRevenue: 0,
                  averageRating: providerRes.data?.rating || 4.5,
                });
              }
            } catch (appointmentError) {
              console.log('Could not fetch appointments, using demo data...');
              // Set demo appointment data
              setAppointments([]);
              setStats({
                totalAppointments: 0,
                completedAppointments: 0,
                upcomingAppointments: 0,
                totalRevenue: 0,
                averageRating: providerRes.data?.rating || 4.5,
              });
            }
          }
        } catch (providerError) {
          console.log('Provider not found, redirecting to registration...');
          // Redirect to provider registration
          navigate('/provider/register');
          return;
        }

        // Fetch appointments for this provider
        try {
          const appointmentsRes = await appointmentService.getByProvider(providerId);
          if (appointmentsRes.data) {
            setAppointments(appointmentsRes.data);

            // Calculate stats
            const completed = appointmentsRes.data.filter(apt => apt.status === 'Completed').length;
            const upcoming = appointmentsRes.data.filter(apt => apt.status === 'Scheduled').length;
            const revenue = appointmentsRes.data
              .filter(apt => apt.status === 'Completed')
              .reduce((sum, apt) => sum + (apt.fee || 0), 0);

            setStats({
              totalAppointments: appointmentsRes.data.length,
              completedAppointments: completed,
              upcomingAppointments: upcoming,
              totalRevenue: revenue,
              averageRating: currentProvider?.rating || 4.5,
            });
          } else {
            // No appointments found, set default stats
            setStats({
              totalAppointments: 0,
              completedAppointments: 0,
              upcomingAppointments: 0,
              totalRevenue: 0,
              averageRating: currentProvider?.rating || 4.5,
            });
          }
        } catch (appointmentError) {
          console.log('Could not fetch appointments, using demo data...');
          // Set demo appointment data
          setAppointments([]);
          setStats({
            totalAppointments: 0,
            completedAppointments: 0,
            upcomingAppointments: 0,
            totalRevenue: 0,
            averageRating: currentProvider?.rating || 4.5,
          });
        }
      } catch (error) {
        toast.error('Failed to load provider data');
        console.error('Provider dashboard error:', error);
      } finally {
        setLoading(false);
      }
    }

    fetchProviderData();
  }, []);

  const upcomingAppointments = appointments
    .filter(apt => apt.status === 'Scheduled')
    .slice(0, 5)
    .sort((a, b) => new Date(a.appointmentDate) - new Date(b.appointmentDate));

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <Spinner size="lg" />
        <p style={styles.loadingText}>Loading provider dashboard...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <PageHeader
        title={`Welcome, ${provider?.fullName || 'Provider'}`}
        subtitle="Manage your appointments and practice"
        actions={
          <div style={styles.headerActions}>
            <Button variant="ghost" size="sm" onClick={() => navigate('/provider/profile')}>
              <Settings size={16} style={{ marginRight: 6 }} />
              Profile Settings
            </Button>
            <Button variant="dark" size="sm" onClick={() => navigate('/provider/availability')}>
              <Calendar size={16} style={{ marginRight: 6 }} />
              Manage Availability
            </Button>
          </div>
        }
      />

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <StatCard
          label="Total Appointments"
          value={stats.totalAppointments}
          icon={Calendar}
          color="#00b5a3"
        />
        <StatCard
          label="Completed"
          value={stats.completedAppointments}
          icon={CheckCircle}
          color="#10b981"
        />
        <StatCard
          label="Upcoming"
          value={stats.upcomingAppointments}
          icon={Clock}
          color="#f59e0b"
        />
        <StatCard
          label="Total Revenue"
          value={`$${stats.totalRevenue.toFixed(2)}`}
          icon={DollarSign}
          color="#6366f1"
        />
        <StatCard
          label="Average Rating"
          value={stats.averageRating.toFixed(1)}
          icon={Star}
          color="#8b5cf6"
        />
      </div>

      <div style={styles.contentGrid}>
        {/* Upcoming Appointments */}
        <Card style={styles.card}>
          <div style={styles.cardHeader}>
            <h3 style={styles.cardTitle}>Upcoming Appointments</h3>
            <Button variant="ghost" size="sm" onClick={() => navigate('/appointments')}>
              View All
            </Button>
          </div>
          <div style={styles.appointmentsList}>
            {upcomingAppointments.length === 0 ? (
              <div style={styles.emptyState}>
                <Calendar size={48} color="#e2e8f0" />
                <p style={styles.emptyText}>No upcoming appointments</p>
              </div>
            ) : (
              upcomingAppointments.map((appointment) => (
                <div key={appointment.appointmentId} style={styles.appointmentItem}>
                  <div style={styles.appointmentInfo}>
                    <div style={styles.appointmentHeader}>
                      <h4 style={styles.patientName}>{appointment.patientName || 'Patient'}</h4>
                      <StatusBadge status={appointment.status} />
                    </div>
                    <div style={styles.appointmentDetails}>
                      <p style={styles.appointmentDate}>
                        {format(new Date(appointment.appointmentDate), 'MMM dd, yyyy')}
                      </p>
                      <p style={styles.appointmentTime}>{appointment.startTime}</p>
                      <p style={styles.appointmentType}>{appointment.serviceType}</p>
                    </div>
                  </div>
                  <div style={styles.appointmentActions}>
                    <Button variant="ghost" size="sm" onClick={() => navigate(`/appointments/${appointment.appointmentId}`)}>
                      <Eye size={16} />
                    </Button>
                  </div>
                </div>
              ))
            )}
          </div>
        </Card>

        {/* Provider Profile Summary */}
        <Card style={styles.card}>
          <div style={styles.cardHeader}>
            <h3 style={styles.cardTitle}>Profile Summary</h3>
            <Button variant="ghost" size="sm" onClick={() => navigate('/provider/profile')}>
              <Edit size={16} />
            </Button>
          </div>
          <div style={styles.profileContent}>
            <div style={styles.profileInfo}>
              <div style={styles.profileItem}>
                <span style={styles.profileLabel}>Specialization:</span>
                <span style={styles.profileValue}>{provider?.specialization || 'Not specified'}</span>
              </div>
              <div style={styles.profileItem}>
                <span style={styles.profileLabel}>Experience:</span>
                <span style={styles.profileValue}>{provider?.experience || '0'} years</span>
              </div>
              <div style={styles.profileItem}>
                <span style={styles.profileLabel}>Verification Status:</span>
                <StatusBadge status={provider?.isVerified ? 'Verified' : 'Pending'} />
              </div>
              <div style={styles.profileItem}>
                <span style={styles.profileLabel}>Average Rating:</span>
                <div style={styles.ratingContainer}>
                  <Star size={16} color="#f59e0b" fill="#f59e0b" />
                  <span style={styles.profileValue}>{stats.averageRating.toFixed(1)}</span>
                </div>
              </div>
            </div>
            <div style={styles.quickActions}>
              <Button variant="dark" size="sm" onClick={() => navigate('/provider/availability')}>
                <Plus size={16} style={{ marginRight: 6 }} />
                Add Availability
              </Button>
              <Button variant="ghost" size="sm" onClick={() => navigate('/provider/reviews')}>
                <Star size={16} style={{ marginRight: 6 }} />
                View Reviews
              </Button>
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: '24px',
    backgroundColor: '#f8fafc',
    minHeight: '100vh',
  },
  loadingContainer: {
